{"tool":"write_file","args":{"path":"contacts/storage.py","content":"import json
import os


class ContactBook:
    """A tiny contacts book backed by a JSON file on disk.

    The file layout is a JSON object with a top-level ``contacts`` list:
        {"contacts": [{"id": 1, "name": "...", "email": "..."}, ...]}

    Every mutating operation rewrites the whole file, so the book is
    always consistent with disk after it returns.
    """

    def __init__(self, path):
        self.path = path
        self.contacts = []
        self._load()

    def _load(self):
        """Read contacts from disk, tolerating a missing file."""
        if not os.path.exists(self.path):
            return
        try:
            with open(self.path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except (json.JSONDecodeError, OSError):
            return
        self.contacts = data.get("contacts", [])
        if not isinstance(self.contacts, list):
            self.contacts = []
        for contact in self.contacts:
            if not isinstance(contact, dict):
                continue
            if "id" not in contact or "name" not in contact or "email" not in contact:
                continue
            contact["id"] = int(contact["id"])

    def _save(self):
        """Write the current contacts back to disk atomically."""
        directory = os.path.dirname(os.path.abspath(self.path))
        if directory and not os.path.isdir(directory):
            os.makedirs(directory, exist_ok=True)
        tmp_path = self.path + ".tmp"
        with open(tmp_path, "w", encoding="utf-8") as fh:
            json.dump({"contacts": self.contacts}, fh, indent=2)
            fh.write("\n")
        os.replace(tmp_path, self.path)

    def add(self, name, email):
        """Add a contact and return its new integer id."""
        contact = {"id": len(self.contacts) + 1, "name": name, "email": email}
        self.contacts.append(contact)
        self._save()
        return contact["id"]

    def remove(self, contact_id):
        """Remove the contact with ``contact_id``; return True or False."""
        for index, contact in enumerate(self.contacts):
            if contact["id"] == contact_id:
                del self.contacts[index]
                self._save()
                return True
        return False

    def find(self, term):
        """Return contacts whose name or email contains ``term`` (case-insensitive)."""
        term = term.lower()
        return [
            contact
            for contact in self.contacts
            if term in contact["name"].lower() or term in contact["email"].lower()
        ]

    def list(self):
        """Return all contacts in the order they were added."""
        return list(self.contacts)
